<main class="content container-fluid"><div class="page-toolbar"><a class="btn btn-outline-secondary" href="<?=url('/admin/usuarios')?>">← Volver a usuarios</a><a class="btn btn-brand" href="<?=url('/admin/usuarios/formulario?id='.$user['id'])?>">Editar usuario</a></div><section class="card panel-card record-card mx-auto"><div class="card-body p-4 p-lg-5"><div class="d-flex flex-column flex-md-row align-items-md-center gap-3 pb-4 border-bottom"><span class="avatar-lg"><?=e(substr($user['first_name'],0,1).substr($user['last_name'],0,1))?></span><div class="flex-grow-1"><span class="eyebrow">PERFIL DE USUARIO</span><h2 class="mt-2 mb-1"><?=e($user['first_name'].' '.$user['last_name'])?></h2><p class="text-secondary mb-0"><?=e($user['email'])?></p></div><span class="badge rounded-pill fs-6 <?=$user['active']?'text-bg-success':'text-bg-secondary'?>"><?=$user['active']?'Activo':'Inactivo'?></span></div><div class="row g-3 py-4"><?php foreach([['Rol',ucfirst($user['role'])],['Asignatura',$user['subject']??'Sin asignatura'],['Teléfono',$user['phone']?:'No informado'],['Acceso a tests',$user['test_enabled']?'Habilitado':'No habilitado'],['Acceso a tabuladores',$user['tabulator_enabled']?'Habilitado':'No habilitado'],['Creado',$user['created_at']]] as $d):?><div class="col-md-6 col-xl-4"><div class="detail-box"><span><?=e($d[0])?></span><strong><?=e($d[1])?></strong></div></div><?php endforeach;?></div><form class="danger-zone" method="post" action="<?=url('/admin/usuarios/eliminar')?>" onsubmit="return confirm('¿Eliminar definitivamente este usuario?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$user['id']?>"><div><strong>Eliminar cuenta</strong><p class="mb-0 text-secondary">Esta acción elimina el registro del usuario.</p></div><button class="btn btn-outline-danger" type="submit">Eliminar usuario</button></form></div></section></main>
